import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;

public class Second {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());
        String line = reader.readLine();
        char[] characters = line.toCharArray();

        int maxSegmentLength = 0;
        int bracketsCount = 0;
        StringBuilder outsideBuilder = new StringBuilder();
        StringBuilder insideBuilder = new StringBuilder();

        for (int i = 0; i < n; i++) {
            if (characters[i] == '(') {
                outsideBuilder.append("_");
                i++;
                while (i < n && characters[i] != ')') {
                    insideBuilder.append(characters[i]);
                    i++;
                }
                insideBuilder.append("_");
            } else {
                outsideBuilder.append(characters[i]);
            }
        }

        String[] outsideParts = outsideBuilder.toString().split("_");
        for (String part : outsideParts) {
            maxSegmentLength = Math.max(maxSegmentLength, part.length());
        }

        String[] insideParts = insideBuilder.toString().split("_");
        for (String part : insideParts) {
            if (part.length() > 0) {
                bracketsCount++;
            }
        }

        System.out.println(maxSegmentLength + " " + bracketsCount);
        reader.close();
    }
}
